mapper.insert:
INSERT INTO WISHLIST (USER_ID, REG_ID)
SELECT #{userId}, #{regId}
FROM dual
WHERE NOT EXISTS (
  SELECT 1
  FROM WISHLIST
  WHERE USER_ID = #{userId}
    AND REG_ID  = #{regId}
)

mapper.delete:
DELETE FROM WISHLIST
 WHERE USER_ID = #{userId}
   AND REG_ID  = #{regId}

mapper.select:
SELECT COUNT(*)
  FROM WISHLIST
 WHERE USER_ID = #{userId}
   AND REG_ID  = #{regId}
